def find_escape_square(threats, king):
    r = len(threats) // 2 + 1
    for x in range(king[0] - r, king[0] + r + 1):
        sq = (x, king[1] + r)
        if sq not in threats:
            return sq
    raise RuntimeError('Impossible by Fundamental Escape Inequality')

def barrier_completeness_radius(threats, king):
    max_r = (len(threats) - 1) // 2
    for r in range(1, max_r + 1):
        sphere = chebyshev_sphere(king, r)
        if not all(sq in threats for sq in sphere):
            return r - 1
    return max_r
